import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_M = 21;
    static final double EPS = 1e-6;
    static int total = 0, selected_k, total_m;
    static double[] probabilities = new double[MAX_M];
    static int[] indices = new int[MAX_M];
    static double[] dynamic = new double[1 << MAX_M];
    static double[] result = new double[MAX_M];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        total_m = Integer.parseInt(st.nextToken());
        selected_k = Integer.parseInt(st.nextToken());

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < total_m; i++) {
            double val = Double.parseDouble(st.nextToken());
            if (val > EPS) {
                probabilities[total] = val;
                indices[total] = i;
                total++;
            } else {
                result[i] = 0.0;
            }
        }

        if (selected_k >= total) {
            for (int i = 0; i < total; i++) {
                result[indices[i]] = 1.0;
            }
        } else {
            Arrays.fill(dynamic, 0.0);
            dynamic[0] = 1.0;
            int maxMask = 1 << total;
            for (int mask = 0; mask < maxMask; mask++) {
                if (Integer.bitCount(mask) < selected_k) {
                    double sum_probs = 0.0;
                    for (int t = 0; t < total; t++) {
                        if (((mask >> t) & 1) == 0) {
                            sum_probs += probabilities[t];
                        }
                    }
                    if (sum_probs > 0) {
                        for (int t = 0; t < total; t++) {
                            if (((mask >> t) & 1) == 0) {
                                int nextMask = mask ^ (1 << t);
                                dynamic[nextMask] += probabilities[t] / sum_probs * dynamic[mask];
                            }
                        }
                    }
                }
            }
            for (int mask = 0; mask < maxMask; mask++) {
                if (Integer.bitCount(mask) == selected_k) {
                    for (int t = 0; t < total; t++) {
                        if (((mask >> t) & 1) == 1) {
                            result[indices[t]] += dynamic[mask];
                        }
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < total_m; i++) {
            sb.append(result[i]).append(" ");
        }
        System.out.println(sb.toString().trim());
    }
}
